final class Counter {
  private val lock  = new Object     // dedicated, never `this`
  private var total = 0L
  private var hits  = 0

  def add(delta: Long): Unit = lock.synchronized {
    total += delta                     // invariant spans both fields
    hits += 1
  }
  def snapshot: (Long, Int) = lock.synchronized((total, hits))
}

