final class Counter {
  private val lock  = new Object     // dedicated, never `this`
  private var total = 0L
  private var hits  = 0

  def add(delta: Long): Unit = lock.synchronized {
    total += delta                     // invariant spans both fields
    hits += 1
  }
  def snapshot: (Long, Int) = lock.synchronized((total, hits))
}

final class Counter(ref: Ref[IO, Long]) {
  def add(delta: Long): IO[Unit] =
    ref.update(_ + delta)              // atomic read-modify-write
  def snapshot: IO[Long] = ref.get     // no lock, no blocked thread
}

object Counter {
  def create: IO[Counter] = Ref[IO].of(0L).map(new Counter(_))
}
